-- Fresh media-model tables. This resource is not in the active migration chain yet.
-- Facts carry no media kind, eligibility, canonical flag or runtime qualification.
CREATE TABLE romd."Roms" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OriginalFilename" varchar(500) NOT NULL,
    "ContentSha256" bytea NOT NULL CHECK (octet_length("ContentSha256") = 32 AND "ContentSha256" <> decode(repeat('00',32),'hex')),
    "ContentSize" bigint NOT NULL CHECK ("ContentSize" >= 0),
    "Sha1" bytea NOT NULL CHECK (octet_length("Sha1") = 20 AND "Sha1" <> decode(repeat('00',20),'hex')),
    "Md5" bytea NOT NULL CHECK (octet_length("Md5") = 16 AND "Md5" <> decode(repeat('00',16),'hex')),
    "Crc32" bytea NOT NULL CHECK (octet_length("Crc32") = 4),
    "PreferredOutputId" integer,
    "CreatedAt" bigint NOT NULL,
    "CreatedByUserId" uuid NOT NULL,
    UNIQUE ("ContentSha256")
);
CREATE TABLE romd."Representations" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FileId" integer NOT NULL REFERENCES romd."Files" ("Id") ON DELETE RESTRICT,
    "Encoding" varchar(32) NOT NULL CHECK ("Encoding" IN ('Identity', 'Rvz', 'Chd'))
);
-- Identical artifact bytes may have distinct immutable original layouts (CUE text or BIN grouping).
CREATE INDEX "IX_Representations_FileEncoding" ON romd."Representations" ("FileId", "Encoding");
CREATE TABLE romd."ReconstructionManifests" (
    "RepresentationId" integer PRIMARY KEY REFERENCES romd."Representations" ("Id") ON DELETE CASCADE,
    "LogicalFrames" bigint NOT NULL CHECK ("LogicalFrames" BETWEEN 1 AND 450000)
);
CREATE TABLE romd."ReconstructionTracks" (
    "RepresentationId" integer NOT NULL REFERENCES romd."ReconstructionManifests" ("RepresentationId") ON DELETE CASCADE,
    "Number" integer NOT NULL CHECK ("Number" BETWEEN 1 AND 99),
    "FirstFrame" bigint NOT NULL CHECK ("FirstFrame" >= 0),
    "Frames" integer NOT NULL CHECK ("Frames" BETWEEN 1 AND 450000),
    "Kind" varchar(32) NOT NULL CHECK ("Kind" IN ('Mode1Raw', 'Mode2Raw', 'Audio')),
    PRIMARY KEY ("RepresentationId", "Number")
);
CREATE TABLE romd."ReconstructionMembers" (
    "RepresentationId" integer NOT NULL REFERENCES romd."ReconstructionManifests" ("RepresentationId") ON DELETE CASCADE,
    "Ordinal" integer NOT NULL CHECK ("Ordinal" BETWEEN 0 AND 198),
    "Path" varchar(240) NOT NULL,
    "ContentSha256" bytea NOT NULL CHECK (octet_length("ContentSha256") = 32 AND "ContentSha256" <> decode(repeat('00',32),'hex')),
    "ContentSize" bigint NOT NULL CHECK ("ContentSize" BETWEEN 1 AND 1058400000),
    "Sha1" bytea NOT NULL CHECK (octet_length("Sha1") = 20 AND "Sha1" <> decode(repeat('00',20),'hex')),
    "Md5" bytea NOT NULL CHECK (octet_length("Md5") = 16 AND "Md5" <> decode(repeat('00',16),'hex')),
    "Crc32" bytea NOT NULL CHECK (octet_length("Crc32") = 4),
    "StoredFileId" integer REFERENCES romd."Files" ("Id") ON DELETE RESTRICT,
    "StoredRole" varchar(32),
    PRIMARY KEY ("RepresentationId", "Ordinal"),
    CHECK (("StoredFileId" IS NULL AND "StoredRole" IS NULL) OR
        ("StoredFileId" IS NOT NULL AND "StoredRole" IS NOT NULL AND "StoredRole" IN ('Cue', 'Sidecar') AND "ContentSize" <= 16777216))
);
-- pg_c_utf8 supplies Unicode simple uppercase independently of the database's C locale.
-- OrdinalIgnoreCase intentionally keeps dotless i and long s distinct from ASCII I/S.
CREATE FUNCTION romd.media_member_path_key(path text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE SET search_path = '' AS $body$
    SELECT string_agg(CASE WHEN value IN (chr(305),chr(383)) THEN value
        ELSE upper(value COLLATE pg_catalog.pg_c_utf8) END, '' ORDER BY ordinal)
    FROM regexp_split_to_table(path,'') WITH ORDINALITY AS chars(value,ordinal)
$body$;
CREATE UNIQUE INDEX "IX_ReconstructionMembers_PortablePath" ON romd."ReconstructionMembers"
    ("RepresentationId", romd.media_member_path_key("Path"));
CREATE TABLE romd."ReconstructionMemberTracks" (
    "RepresentationId" integer NOT NULL,
    "MemberOrdinal" integer NOT NULL,
    "TrackNumber" integer NOT NULL,
    PRIMARY KEY ("RepresentationId", "TrackNumber"),
    FOREIGN KEY ("RepresentationId", "MemberOrdinal") REFERENCES romd."ReconstructionMembers" ("RepresentationId", "Ordinal") ON DELETE CASCADE,
    FOREIGN KEY ("RepresentationId", "TrackNumber") REFERENCES romd."ReconstructionTracks" ("RepresentationId", "Number") ON DELETE CASCADE
);
CREATE TABLE romd."RepresentationOutputs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RepresentationId" integer NOT NULL REFERENCES romd."Representations" ("Id") ON DELETE CASCADE,
    "MemberOrdinal" integer,
    "RomId" integer REFERENCES romd."Roms" ("Id") ON DELETE SET NULL,
    "ContentSha256" bytea NOT NULL CHECK (octet_length("ContentSha256") = 32 AND "ContentSha256" <> decode(repeat('00',32),'hex')),
    "ContentSize" bigint NOT NULL CHECK ("ContentSize" >= 0),
    "Sha1" bytea NOT NULL CHECK (octet_length("Sha1") = 20 AND "Sha1" <> decode(repeat('00',20),'hex')),
    "Md5" bytea NOT NULL CHECK (octet_length("Md5") = 16 AND "Md5" <> decode(repeat('00',16),'hex')),
    "Crc32" bytea NOT NULL CHECK (octet_length("Crc32") = 4),
    UNIQUE NULLS NOT DISTINCT ("RepresentationId", "MemberOrdinal"),
    UNIQUE ("Id", "RomId"),
    UNIQUE ("Id", "RepresentationId"),
    FOREIGN KEY ("RepresentationId", "MemberOrdinal") REFERENCES romd."ReconstructionMembers" ("RepresentationId", "Ordinal") ON DELETE CASCADE
);
ALTER TABLE romd."Roms" ADD CONSTRAINT "FK_Roms_PreferredOutput"
    FOREIGN KEY ("PreferredOutputId", "Id") REFERENCES romd."RepresentationOutputs" ("Id", "RomId") DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE romd."Verifications" (
    "Id" uuid PRIMARY KEY CHECK ("Id" <> '00000000-0000-0000-0000-000000000000'),
    "RepresentationId" integer NOT NULL REFERENCES romd."Representations" ("Id") ON DELETE CASCADE,
    "ArtifactSha256" bytea NOT NULL CHECK (octet_length("ArtifactSha256") = 32 AND "ArtifactSha256" <> decode(repeat('00',32),'hex')),
    "ArtifactSize" bigint NOT NULL CHECK ("ArtifactSize" >= 0),
    "DecoderBuild" varchar(256) NOT NULL CHECK (btrim("DecoderBuild") <> '' AND "DecoderBuild" !~ '[[:cntrl:]]'),
    "DecoderRid" varchar(32),
    "DecoderUpstreamCommit" bytea,
    "DecoderRecipeVersion" integer,
    "CheckedProfile" varchar(128) NOT NULL CHECK (btrim("CheckedProfile") <> '' AND "CheckedProfile" !~ '[[:cntrl:]]'),
    "VerifierBuild" varchar(256) NOT NULL CHECK (btrim("VerifierBuild") <> '' AND "VerifierBuild" !~ '[[:cntrl:]]'),
    "ObservedAtUtcTicks" bigint NOT NULL CHECK ("ObservedAtUtcTicks" BETWEEN 0 AND 3155378975999999999),
    UNIQUE ("Id", "RepresentationId"),
    CHECK (("DecoderRid" IS NULL AND "DecoderUpstreamCommit" IS NULL AND "DecoderRecipeVersion" IS NULL) OR
        ("DecoderRid" IS NOT NULL AND "DecoderUpstreamCommit" IS NOT NULL AND "DecoderRecipeVersion" IS NOT NULL AND "DecoderRid" ~ '^[a-z0-9.-]{1,32}$' AND octet_length("DecoderUpstreamCommit") = 20 AND "DecoderUpstreamCommit" <> decode(repeat('00',20),'hex') AND "DecoderRecipeVersion" >= 1))
);
CREATE UNIQUE INDEX "IX_Verifications_ManagedBuild" ON romd."Verifications" ("RepresentationId", "DecoderBuild") WHERE "DecoderRid" IS NULL;
CREATE UNIQUE INDEX "IX_Verifications_NativeBuild" ON romd."Verifications" ("RepresentationId", "DecoderRid", "DecoderUpstreamCommit", "DecoderRecipeVersion") WHERE "DecoderRid" IS NOT NULL;
CREATE TABLE romd."VerificationOutputs" (
    "VerificationId" uuid NOT NULL,
    "RepresentationId" integer NOT NULL,
    "OutputId" integer NOT NULL,
    "ContentSha256" bytea NOT NULL CHECK (octet_length("ContentSha256") = 32 AND "ContentSha256" <> decode(repeat('00',32),'hex')),
    "ContentSize" bigint NOT NULL CHECK ("ContentSize" >= 0),
    "Sha1" bytea NOT NULL CHECK (octet_length("Sha1") = 20 AND "Sha1" <> decode(repeat('00',20),'hex')),
    "Md5" bytea NOT NULL CHECK (octet_length("Md5") = 16 AND "Md5" <> decode(repeat('00',16),'hex')),
    "Crc32" bytea NOT NULL CHECK (octet_length("Crc32") = 4),
    PRIMARY KEY ("VerificationId", "OutputId"),
    FOREIGN KEY ("VerificationId", "RepresentationId") REFERENCES romd."Verifications" ("Id", "RepresentationId") ON DELETE CASCADE,
    FOREIGN KEY ("OutputId", "RepresentationId") REFERENCES romd."RepresentationOutputs" ("Id", "RepresentationId") ON DELETE CASCADE
);
-- Publication transactions lock logical identities before the representation they measure.
CREATE FUNCTION romd.guard_media_fact_verification() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
DECLARE encoding text; artifact_file_id integer;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'Verification facts are immutable' USING ERRCODE = '23514';
    ELSIF TG_OP = 'DELETE' THEN
        IF EXISTS (SELECT 1 FROM romd."Representations" WHERE "Id" = OLD."RepresentationId") THEN
            RAISE EXCEPTION 'Retained decoder measurements cannot be removed' USING ERRCODE = '23514';
        END IF;
        RETURN OLD;
    END IF;
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'Media publication requires ReadCommitted current artifact authority' USING ERRCODE = '23514';
    END IF;
    PERFORM 1 FROM romd."Roms" WHERE "Id" IN (
        SELECT "RomId" FROM romd."RepresentationOutputs" WHERE "RepresentationId" = NEW."RepresentationId"
    ) ORDER BY "Id" FOR NO KEY UPDATE;
    PERFORM pg_advisory_xact_lock(9415, NEW."RepresentationId");
    SELECT "Encoding", "FileId" INTO encoding, artifact_file_id FROM romd."Representations"
        WHERE "Id" = NEW."RepresentationId" FOR NO KEY UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Measurement representation is missing' USING ERRCODE = '23514';
    END IF;
    -- A descriptor may have had no media owner when a concurrent file edit began.
    -- Lock every artifact dependency before checking its retained identity, in one stable order.
    PERFORM 1 FROM romd."Files" WHERE "Id" IN (
        SELECT artifact_file_id UNION SELECT "StoredFileId" FROM romd."ReconstructionMembers"
            WHERE "RepresentationId" = NEW."RepresentationId"
    ) ORDER BY "Id" FOR NO KEY UPDATE;
    IF NOT EXISTS (SELECT 1 FROM romd."Files" WHERE "Id" = artifact_file_id
        AND "Sha256" = NEW."ArtifactSha256" AND "Size" = NEW."ArtifactSize") OR
        (encoding = 'Chd') IS DISTINCT FROM (NEW."DecoderRid" IS NOT NULL) THEN
        RAISE EXCEPTION 'Measurement must describe its exact artifact and decoder identity' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $body$;
CREATE TRIGGER "TR_Verifications_ImmutableFacts" BEFORE INSERT OR UPDATE OR DELETE ON romd."Verifications"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_verification();

CREATE FUNCTION romd.guard_media_fact_verification_output() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'Measured output facts are immutable' USING ERRCODE = '23514';
    ELSIF TG_OP = 'DELETE' THEN
        IF EXISTS (SELECT 1 FROM romd."Representations" WHERE "Id" = OLD."RepresentationId") THEN
            RAISE EXCEPTION 'Retained measured outputs cannot be removed' USING ERRCODE = '23514';
        END IF;
        RETURN OLD;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM romd."RepresentationOutputs" o WHERE o."Id" = NEW."OutputId" AND o."RepresentationId" = NEW."RepresentationId"
        AND (o."ContentSha256", o."ContentSize", o."Sha1", o."Md5", o."Crc32") =
            (NEW."ContentSha256", NEW."ContentSize", NEW."Sha1", NEW."Md5", NEW."Crc32")
    ) THEN
        RAISE EXCEPTION 'Measured output does not match its declared logical identity' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $body$;
CREATE TRIGGER "TR_VerificationOutputs_ImmutableFacts" BEFORE INSERT OR UPDATE OR DELETE ON romd."VerificationOutputs"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_verification_output();

CREATE FUNCTION romd.check_media_fact_verification() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
DECLARE verification_id uuid; representation_id integer; expected integer;
BEGIN
    IF TG_TABLE_NAME = 'Verifications' THEN
        verification_id := CASE WHEN TG_OP = 'DELETE' THEN OLD."Id" ELSE NEW."Id" END;
    ELSE
        verification_id := CASE WHEN TG_OP = 'DELETE' THEN OLD."VerificationId" ELSE NEW."VerificationId" END;
    END IF;
    SELECT "RepresentationId" INTO representation_id FROM romd."Verifications" WHERE "Id" = verification_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT count(*) INTO expected FROM romd."RepresentationOutputs" WHERE "RepresentationId" = representation_id;
    IF expected = 0 OR expected <> (SELECT count(*) FROM romd."VerificationOutputs" WHERE "VerificationId" = verification_id) THEN
        RAISE EXCEPTION 'Verification publication requires every exact output in one transaction' USING ERRCODE = '23514';
    END IF;
    PERFORM romd.validate_media_container_facts(representation_id);
    RETURN NULL;
END $body$;
CREATE CONSTRAINT TRIGGER "TR_Verifications_CompletePublication" AFTER INSERT OR DELETE ON romd."Verifications"
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION romd.check_media_fact_verification();
CREATE CONSTRAINT TRIGGER "TR_VerificationOutputs_CompletePublication" AFTER INSERT OR DELETE ON romd."VerificationOutputs"
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION romd.check_media_fact_verification();

CREATE FUNCTION romd.guard_media_fact_rom() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
BEGIN
    IF (NEW."Id", NEW."ContentSha256", NEW."ContentSize", NEW."Sha1", NEW."Md5", NEW."Crc32") IS DISTINCT FROM
       (OLD."Id", OLD."ContentSha256", OLD."ContentSize", OLD."Sha1", OLD."Md5", OLD."Crc32") AND EXISTS (
        SELECT 1 FROM romd."RepresentationOutputs" o JOIN romd."Verifications" v ON v."RepresentationId" = o."RepresentationId"
        WHERE o."RomId" = OLD."Id"
    ) THEN
        RAISE EXCEPTION 'Verified logical identities are immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $body$;
CREATE TRIGGER "TR_Roms_ImmutableIdentity" BEFORE UPDATE ON romd."Roms"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_rom();

CREATE FUNCTION romd.guard_media_fact_representation() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
BEGIN
    PERFORM pg_advisory_xact_lock(9415, OLD."Id");
    IF (NEW."Id", NEW."FileId", NEW."Encoding") IS DISTINCT FROM
       (OLD."Id", OLD."FileId", OLD."Encoding") AND EXISTS (
        SELECT 1 FROM romd."Verifications" WHERE "RepresentationId" = OLD."Id"
    ) THEN
        RAISE EXCEPTION 'Verified artifact facts are immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $body$;
CREATE TRIGGER "TR_Representations_ImmutableFacts" BEFORE UPDATE ON romd."Representations"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_representation();

CREATE FUNCTION romd.guard_media_fact_output() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
DECLARE representation_id integer;
BEGIN
    representation_id := CASE WHEN TG_OP = 'DELETE' THEN OLD."RepresentationId" ELSE NEW."RepresentationId" END;
    -- Attachment participates in the same logical-identity serialization as verification.
    -- KEY SHARE from the FK alone does not conflict with an identity-column update.
    PERFORM 1 FROM romd."Roms" WHERE "Id" IN (
        CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD."RomId" END,
        CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE NEW."RomId" END
    ) ORDER BY "Id" FOR UPDATE;
    IF TG_OP = 'UPDATE' THEN
        PERFORM pg_advisory_xact_lock(9415, least(OLD."RepresentationId", NEW."RepresentationId"));
        PERFORM pg_advisory_xact_lock(9415, greatest(OLD."RepresentationId", NEW."RepresentationId"));
    ELSE
        PERFORM pg_advisory_xact_lock(9415, representation_id);
    END IF;
    IF TG_OP = 'UPDATE' AND
        (NEW."Id", NEW."RepresentationId", NEW."MemberOrdinal", NEW."ContentSha256", NEW."ContentSize", NEW."Sha1", NEW."Md5", NEW."Crc32") IS NOT DISTINCT FROM
        (OLD."Id", OLD."RepresentationId", OLD."MemberOrdinal", OLD."ContentSha256", OLD."ContentSize", OLD."Sha1", OLD."Md5", OLD."Crc32") THEN
        RETURN NEW; -- Logical catalog withdrawal/re-attachment does not rewrite output facts.
    END IF;
    IF EXISTS (SELECT 1 FROM romd."Verifications" WHERE "RepresentationId" IN
        (representation_id, CASE WHEN TG_OP = 'UPDATE' THEN OLD."RepresentationId" ELSE representation_id END)) AND
       EXISTS (SELECT 1 FROM romd."Representations" WHERE "Id" = representation_id) THEN
        RAISE EXCEPTION 'Verified output selections are immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $body$;
CREATE TRIGGER "TR_RepresentationOutputs_ImmutableFacts" BEFORE INSERT OR UPDATE OR DELETE ON romd."RepresentationOutputs"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_output();

CREATE FUNCTION romd.guard_media_fact_file() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
BEGIN
    IF (NEW."Sha256", NEW."Size") IS DISTINCT FROM (OLD."Sha256", OLD."Size") AND EXISTS (
        SELECT 1 FROM romd."Representations" r JOIN romd."Verifications" v ON v."RepresentationId" = r."Id" WHERE r."FileId" = OLD."Id"
        UNION ALL SELECT 1 FROM romd."ReconstructionMembers" m JOIN romd."Verifications" v ON v."RepresentationId" = m."RepresentationId" WHERE m."StoredFileId" = OLD."Id"
    ) THEN
        RAISE EXCEPTION 'Verified artifact identity in the file ledger is immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $body$;
CREATE TRIGGER "TR_Files_MediaFactIdentity" BEFORE UPDATE ON romd."Files"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_file();

CREATE FUNCTION romd.media_fact_portable_path(path text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path = '' AS $body$
    SELECT path <> '' AND char_length(path) <= 240 AND left(path,1) <> '/'
        AND path !~ '[:*?"<>|]' AND position(chr(92) in path) = 0
        AND NOT EXISTS (SELECT 1 FROM generate_series(1,char_length(path)) i
            WHERE ascii(substr(path,i,1)) BETWEEN 0 AND 31 OR ascii(substr(path,i,1)) BETWEEN 127 AND 159)
        AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(path,'/')) part
            WHERE btrim(part) = '' OR part IN ('.','..') OR right(part,1) IN ('.',' '));
$body$;
ALTER TABLE romd."ReconstructionMembers" ADD CONSTRAINT "CK_ReconstructionMembers_PortablePath"
    CHECK (romd.media_fact_portable_path("Path"));

CREATE FUNCTION romd.guard_media_fact_manifest() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
DECLARE representation_id integer;
BEGIN
    representation_id := CASE WHEN TG_OP = 'DELETE' THEN OLD."RepresentationId" ELSE NEW."RepresentationId" END;
    PERFORM pg_advisory_xact_lock(9415, representation_id);
    IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM romd."Representations" WHERE "Id" = representation_id) THEN RETURN OLD; END IF;
    IF TG_OP <> 'INSERT' OR EXISTS (SELECT 1 FROM romd."Verifications" WHERE "RepresentationId" = representation_id) THEN
        RAISE EXCEPTION 'Published reconstruction layout facts are immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $body$;
CREATE TRIGGER "TR_ReconstructionManifests_Immutable" BEFORE INSERT OR UPDATE OR DELETE ON romd."ReconstructionManifests"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_manifest();
CREATE TRIGGER "TR_ReconstructionTracks_Immutable" BEFORE INSERT OR UPDATE OR DELETE ON romd."ReconstructionTracks"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_manifest();
CREATE TRIGGER "TR_ReconstructionMembers_Immutable" BEFORE INSERT OR UPDATE OR DELETE ON romd."ReconstructionMembers"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_manifest();
CREATE TRIGGER "TR_ReconstructionMemberTracks_Immutable" BEFORE INSERT OR UPDATE OR DELETE ON romd."ReconstructionMemberTracks"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_media_fact_manifest();

CREATE FUNCTION romd.validate_media_fact_graph(representation_id integer) RETURNS void LANGUAGE plpgsql SET search_path = '' AS $body$
DECLARE encoding text; output_count integer; track_count integer; member_count integer; logical_frames bigint;
BEGIN
    SELECT "Encoding" INTO encoding FROM romd."Representations" WHERE "Id" = representation_id;
    IF NOT FOUND THEN RETURN; END IF;
    SELECT count(*) INTO output_count FROM romd."RepresentationOutputs" WHERE "RepresentationId" = representation_id;
    IF output_count = 0 OR EXISTS (
        SELECT 1 FROM romd."RepresentationOutputs" o JOIN romd."Roms" r ON r."Id" = o."RomId"
        WHERE o."RepresentationId" = representation_id AND
            (o."ContentSha256",o."ContentSize",o."Sha1",o."Md5",o."Crc32") IS DISTINCT FROM
            (r."ContentSha256",r."ContentSize",r."Sha1",r."Md5",r."Crc32")
    ) THEN
        RAISE EXCEPTION 'Representation outputs require complete matching logical identities' USING ERRCODE = '23514';
    END IF;
    PERFORM romd.validate_media_container_facts(representation_id);
    SELECT "LogicalFrames" INTO logical_frames FROM romd."ReconstructionManifests" WHERE "RepresentationId" = representation_id;
    IF NOT FOUND THEN
        IF output_count <> 1 OR EXISTS (SELECT 1 FROM romd."RepresentationOutputs" WHERE "RepresentationId" = representation_id AND "MemberOrdinal" IS NOT NULL) OR
            (encoding = 'Identity' AND EXISTS (
                SELECT 1 FROM romd."RepresentationOutputs" o JOIN romd."Representations" r ON r."Id" = o."RepresentationId"
                JOIN romd."Files" f ON f."Id" = r."FileId" WHERE r."Id" = representation_id AND
                    (f."Sha256",f."Size") IS DISTINCT FROM (o."ContentSha256",o."ContentSize")
            )) THEN
            RAISE EXCEPTION 'Whole-file layouts require exactly one whole output and exact identity bytes' USING ERRCODE = '23514';
        END IF;
        RETURN;
    END IF;
    SELECT count(*) INTO track_count FROM romd."ReconstructionTracks" WHERE "RepresentationId" = representation_id;
    SELECT count(*) INTO member_count FROM romd."ReconstructionMembers" WHERE "RepresentationId" = representation_id;
    IF encoding <> 'Chd' OR track_count NOT BETWEEN 1 AND 99 OR member_count NOT BETWEEN 2 AND 199 OR
        NOT EXISTS (SELECT 1 FROM romd."Verifications" WHERE "RepresentationId" = representation_id) OR
        logical_frames <> (SELECT sum((("Frames" + 3) / 4) * 4) FROM romd."ReconstructionTracks" WHERE "RepresentationId" = representation_id) OR
        EXISTS (
            SELECT 1 FROM (
                SELECT "Number", "FirstFrame", row_number() OVER (ORDER BY "Number") AS ordinal,
                    coalesce(sum((("Frames" + 3) / 4) * 4) OVER (ORDER BY "Number" ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS first_frame
                FROM romd."ReconstructionTracks" WHERE "RepresentationId" = representation_id
            ) tracks WHERE "Number" <> ordinal OR "FirstFrame" <> first_frame
        ) OR EXISTS (
            SELECT 1 FROM (SELECT "Ordinal", row_number() OVER (ORDER BY "Ordinal") - 1 AS expected
                FROM romd."ReconstructionMembers" WHERE "RepresentationId" = representation_id) members WHERE "Ordinal" <> expected
        ) THEN
        RAISE EXCEPTION 'CD publication requires a verified, complete, ordered reconstruction layout' USING ERRCODE = '23514';
    END IF;
    IF (SELECT count(*) FROM romd."ReconstructionMembers" WHERE "RepresentationId" = representation_id AND "StoredRole" = 'Cue') <> 1 OR
        (SELECT count(*) FROM romd."ReconstructionMemberTracks" WHERE "RepresentationId" = representation_id) <> track_count OR
        EXISTS (
            SELECT 1 FROM romd."ReconstructionMembers" m LEFT JOIN romd."Files" f ON f."Id" = m."StoredFileId"
            WHERE m."RepresentationId" = representation_id AND m."StoredFileId" IS NOT NULL AND
                ((f."Sha256",f."Size") IS DISTINCT FROM (m."ContentSha256",m."ContentSize") OR
                EXISTS (SELECT 1 FROM romd."ReconstructionMemberTracks" mt WHERE mt."RepresentationId" = m."RepresentationId" AND mt."MemberOrdinal" = m."Ordinal"))
        ) OR EXISTS (
            SELECT 1 FROM romd."ReconstructionMembers" m LEFT JOIN romd."ReconstructionMemberTracks" mt ON mt."RepresentationId" = m."RepresentationId" AND mt."MemberOrdinal" = m."Ordinal"
            LEFT JOIN romd."ReconstructionTracks" t ON t."RepresentationId" = mt."RepresentationId" AND t."Number" = mt."TrackNumber"
            WHERE m."RepresentationId" = representation_id AND m."StoredFileId" IS NULL
            GROUP BY m."Ordinal",m."ContentSize" HAVING count(t."Number") = 0 OR
                count(t."Number") <> max(t."Number") - min(t."Number") + 1 OR sum(t."Frames"::bigint * 2352) <> m."ContentSize"
        ) THEN
        RAISE EXCEPTION 'CD members require exact retained descriptors and one consecutive BIN owner per track' USING ERRCODE = '23514';
    END IF;
    IF output_count <> (SELECT count(*) FROM romd."ReconstructionMembers" WHERE "RepresentationId" = representation_id AND "StoredFileId" IS NULL) OR
        EXISTS (
            SELECT 1 FROM romd."RepresentationOutputs" o LEFT JOIN romd."ReconstructionMembers" m
                ON m."RepresentationId" = o."RepresentationId" AND m."Ordinal" = o."MemberOrdinal"
            WHERE o."RepresentationId" = representation_id AND (m."Ordinal" IS NULL OR m."StoredFileId" IS NOT NULL OR
                (o."ContentSha256",o."ContentSize",o."Sha1",o."Md5",o."Crc32") IS DISTINCT FROM
                (m."ContentSha256",m."ContentSize",m."Sha1",m."Md5",m."Crc32"))
        ) THEN
        RAISE EXCEPTION 'CD outputs select every exact decoded BIN and never a retained descriptor' USING ERRCODE = '23514';
    END IF;
END $body$;

CREATE FUNCTION romd.check_media_fact_graph() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
DECLARE object_id integer; representation_id integer;
BEGIN
    IF TG_TABLE_NAME = 'Roms' THEN
        object_id := CASE WHEN TG_OP = 'DELETE' THEN OLD."Id" ELSE NEW."Id" END;
        IF EXISTS (SELECT 1 FROM romd."Roms" WHERE "Id" = object_id AND "PreferredOutputId" IS NULL) THEN
            RAISE EXCEPTION 'A logical ROM requires its own preferred output at publication' USING ERRCODE = '23514';
        END IF;
        FOR representation_id IN SELECT "RepresentationId" FROM romd."RepresentationOutputs" WHERE "RomId" = object_id LOOP
            PERFORM romd.validate_media_fact_graph(representation_id);
        END LOOP;
    ELSIF TG_TABLE_NAME = 'Files' THEN
        object_id := CASE WHEN TG_OP = 'DELETE' THEN OLD."Id" ELSE NEW."Id" END;
        FOR representation_id IN
            SELECT "Id" FROM romd."Representations" WHERE "FileId" = object_id
            UNION SELECT "RepresentationId" FROM romd."ReconstructionMembers" WHERE "StoredFileId" = object_id
        LOOP PERFORM romd.validate_media_fact_graph(representation_id); END LOOP;
    ELSIF TG_TABLE_NAME = 'Representations' THEN
        PERFORM romd.validate_media_fact_graph(CASE WHEN TG_OP = 'DELETE' THEN OLD."Id" ELSE NEW."Id" END);
    ELSE
        PERFORM romd.validate_media_fact_graph(CASE WHEN TG_OP = 'DELETE' THEN OLD."RepresentationId" ELSE NEW."RepresentationId" END);
        IF TG_OP = 'UPDATE' AND OLD."RepresentationId" <> NEW."RepresentationId" THEN
            PERFORM romd.validate_media_fact_graph(OLD."RepresentationId");
        END IF;
    END IF;
    RETURN NULL;
END $body$;
DO $body$
DECLARE target text;
BEGIN
    FOREACH target IN ARRAY ARRAY['Roms','Representations','RepresentationOutputs','ReconstructionManifests','ReconstructionTracks','ReconstructionMembers','ReconstructionMemberTracks','Files'] LOOP
        EXECUTE format('CREATE CONSTRAINT TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON romd.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION romd.check_media_fact_graph()',
            'TR_' || target || '_CompleteMediaGraph',target);
    END LOOP;
END $body$;

-- Runtime roles append proof only through this validated, atomic publication entry point.
-- JSON is a strictly typed row transport; it is not persisted as an extensible format bag.
CREATE FUNCTION romd.publish_media_verification(
    p_id uuid, p_representation_id integer, p_artifact_sha256 bytea, p_artifact_size bigint,
    p_decoder_build text, p_decoder_rid text, p_decoder_pin bytea, p_decoder_recipe integer,
    p_checked_profile text, p_verifier_build text, p_observed_ticks bigint, p_observed_parameters_sha256 bytea, p_computed_raw_sha1 bytea, p_computed_overall_sha1 bytea, p_outputs jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $body$
DECLARE item jsonb; output_id integer; seen integer[] := '{}';
    keys text[] := ARRAY['OutputId','ContentSha256','ContentSize','Sha1','Md5','Crc32'];
BEGIN
    IF jsonb_typeof(p_outputs) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'Measured outputs must be a bounded array' USING ERRCODE = '23514';
    END IF;
    IF jsonb_array_length(p_outputs) NOT BETWEEN 1 AND 199 THEN
        RAISE EXCEPTION 'Measured outputs must be a nonempty bounded array' USING ERRCODE = '23514';
    END IF;
    INSERT INTO romd."Verifications" ("Id","RepresentationId","ArtifactSha256","ArtifactSize","DecoderBuild",
        "DecoderRid","DecoderUpstreamCommit","DecoderRecipeVersion","CheckedProfile","VerifierBuild","ObservedAtUtcTicks","ComputedRawSha1","ComputedOverallSha1","ObservedParametersSha256")
    VALUES (p_id,p_representation_id,p_artifact_sha256,p_artifact_size,p_decoder_build,
        p_decoder_rid,p_decoder_pin,p_decoder_recipe,p_checked_profile,p_verifier_build,p_observed_ticks,p_computed_raw_sha1,p_computed_overall_sha1,p_observed_parameters_sha256);
    FOR item IN SELECT value FROM jsonb_array_elements(p_outputs) LOOP
        IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN
            RAISE EXCEPTION 'Measured output must be a typed object' USING ERRCODE = '23514';
        END IF;
        IF NOT (item ?& keys) OR item - keys <> '{}'::jsonb THEN
            RAISE EXCEPTION 'Measured output has missing or unknown facts' USING ERRCODE = '23514';
        END IF;
        IF jsonb_typeof(item->'OutputId') IS DISTINCT FROM 'number' OR
            jsonb_typeof(item->'ContentSize') IS DISTINCT FROM 'number' OR
            jsonb_typeof(item->'ContentSha256') IS DISTINCT FROM 'string' OR
            jsonb_typeof(item->'Sha1') IS DISTINCT FROM 'string' OR
            jsonb_typeof(item->'Md5') IS DISTINCT FROM 'string' OR
            jsonb_typeof(item->'Crc32') IS DISTINCT FROM 'string' THEN
            RAISE EXCEPTION 'Measured output facts have invalid types' USING ERRCODE = '23514';
        END IF;
        output_id := (item->>'OutputId')::integer;
        IF output_id = ANY(seen) THEN
            RAISE EXCEPTION 'Measured output selectors must be unique' USING ERRCODE = '23514';
        END IF;
        seen := array_append(seen,output_id);
        INSERT INTO romd."VerificationOutputs" ("VerificationId","RepresentationId","OutputId","ContentSha256","ContentSize","Sha1","Md5","Crc32")
        VALUES (p_id,p_representation_id,output_id,decode(item->>'ContentSha256','hex'),(item->>'ContentSize')::bigint,
            decode(item->>'Sha1','hex'),decode(item->>'Md5','hex'),decode(item->>'Crc32','hex'));
    END LOOP;
    RETURN p_id;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN
    RAISE EXCEPTION 'Measured output facts have invalid values' USING ERRCODE = '23514';
END $body$;
REVOKE ALL ON FUNCTION romd.publish_media_verification(uuid,integer,bytea,bigint,text,text,bytea,integer,text,text,bigint,bytea,bytea,bytea,jsonb) FROM PUBLIC;
REVOKE ALL ON romd."Verifications",romd."VerificationOutputs" FROM PUBLIC;
DO $body$
DECLARE runtime text;
BEGIN
    FOREACH runtime IN ARRAY ARRAY['romd_worker','romd_admin','romd_consumer'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = runtime) THEN
            EXECUTE format('REVOKE ALL PRIVILEGES ON romd."Verifications",romd."VerificationOutputs" FROM %I',runtime);
            EXECUTE format('REVOKE ALL ON FUNCTION romd.publish_media_verification(uuid,integer,bytea,bigint,text,text,bytea,integer,text,text,bigint,bytea,bytea,bytea,jsonb) FROM %I',runtime);
            EXECUTE format('GRANT SELECT ON romd."Verifications",romd."VerificationOutputs" TO %I',runtime);
        END IF;
    END LOOP;
    FOREACH runtime IN ARRAY ARRAY['romd_admin','romd_consumer'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = runtime) THEN
            EXECUTE format('REVOKE INSERT, UPDATE, DELETE ON romd."Representations",romd."RepresentationOutputs",romd."ReconstructionManifests",romd."ReconstructionTracks",romd."ReconstructionMembers",romd."ReconstructionMemberTracks" FROM %I',runtime);
            EXECUTE format('REVOKE INSERT, UPDATE ON romd."Roms" FROM %I',runtime);
        END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'romd_worker') THEN
        GRANT EXECUTE ON FUNCTION romd.publish_media_verification(uuid,integer,bytea,bigint,text,text,bytea,integer,text,text,bigint,bytea,bytea,bytea,jsonb) TO romd_worker;
    END IF;
END $body$;
